const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();
  await page.goto('http://localhost:5000/pages/level-09/');
  const frame = page.frameLocator('#portal-frame');
  const code = await frame.locator('#secret-code').textContent();
  if (code && code.trim() === 'XYZZY') console.log('LEVEL_PASSED');
  await browser.close();
})();

explanation:
`page.frameLocator(selector)` returns a handle to an `<iframe>`. Once inside, use standard locators to query the iframe's content.

```
const frame = page.frameLocator('#portal-frame');
const code = await frame.locator('#secret-code').textContent();
if (code.trim() === 'XYZZY') console.log('LEVEL_PASSED');
```

The frame must be fully loaded before querying. Playwright waits automatically, but if the iframe loads content dynamically you may need `frame.locator(...).waitFor()`.

