const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();
  await page.goto('http://localhost:5000/pages/level-10/');
  // Add 3 items
  for (const item of ['Slay Dragon', 'Rescue Princess', 'Claim Treasure']) {
    await page.locator('#todo-input').fill(item);
    await page.locator('#add-btn').click();
  }
  // Mark first item complete
  await page.locator('.todo-check').first().check();
  // Delete second item
  await page.locator('.todo-delete').nth(1).click();
  // Verify 2 items remain
  const remaining = await page.locator('.todo-item').count();
  if (remaining === 2) console.log('LEVEL_PASSED');
  await browser.close();
})();

explanation:
This is a full end-to-end flow using multiple Playwright actions together.

Key selectors on the todo page:
• `#todo-input` — text input for new items
• `#add-btn` — adds the item to the list
• `.todo-check` — checkbox on each item (use `.first()`, `.nth(1)`)
• `.todo-delete` — delete button on each item
• `.todo-item` — each row in the list

```
await page.locator('#todo-input').fill('Slay Dragon');
await page.locator('#add-btn').click();
// mark first item complete
await page.locator('.todo-check').first().check();
// delete second item
await page.locator('.todo-delete').nth(1).click();
