const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();
  await page.goto('http://localhost:5000/pages/level-12/');

  // TODO: Register page.on('dialog', async dialog => dialog.accept()) BEFORE clicking
  // Then click '#confirm-btn'
  // Read '#oracle-result' — if it includes 'Challenge Accepted', log: console.log('LEVEL_PASSED')

  await browser.close();
})();

solution:
const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();
  page.on('dialog', async (dialog) => {
    await dialog.accept();
  });
  await page.goto('http://localhost:5000/pages/level-12/');
  await page.locator('#confirm-btn').click();
  const result = await page.locator('#oracle-result').textContent();
  if (result && result.includes('Challenge Accepted')) console.log('LEVEL_PASSED');
  await browser.close();
})();

explanation:
`page.on('dialog', handler)` listens for `alert`, `confirm`, and `prompt` dialogs. **Register the listener before triggering the action that opens the dialog.**

```
page.on('dialog', async (dialog) => {
  console.log('Dialog type:', dialog.type());
  await dialog.accept();       // or dialog.dismiss()
});
await page.locator('#confirm-btn').click();
```

`dialog.accept(promptText)` — accepts the dialog (optionally fills prompt text)
`dialog.dismiss()` — cancels the dialog

