const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();
  await page.goto('http://localhost:5000/pages/level-15/');
  await page.context().addCookies([{
    name: 'vault-access',
    value: 'granted',
    domain: 'localhost',
    path: '/',
  }]);
  await page.reload();
  const vault = page.locator('#vault-content');
  await vault.waitFor({ state: 'visible' });
  console.log('LEVEL_PASSED');
  await browser.close();
})();

explanation:
`context.addCookies(cookies)` sets cookies before or after navigation. The cookie must match the page's domain.

```
await page.context().addCookies([{
  name: 'vault-access',
  value: 'granted',
  domain: 'localhost',
  path: '/',
}]);
await page.reload();
const vault = page.locator('#vault-content');
await vault.waitFor({ state: 'visible' });
console.log('LEVEL_PASSED');
```

After adding cookies, `page.reload()` re-runs the page so it can read the new cookie values.

