solution:
const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();
  await page.goto('http://localhost:5000/pages/level-18/');
  const [popup] = await Promise.all([
    page.waitForEvent('popup'),
    page.locator('#open-portal-btn').click(),
  ]);
  await popup.waitForLoadState();
  const title = await popup.title();
  if (title === 'Secret Portal') console.log('LEVEL_PASSED');
  await browser.close();
})();

explanation:
When a click opens a new tab/window, use `page.waitForEvent('popup')` wrapped in `Promise.all` to capture it before it opens.

```
const [popup] = await Promise.all([
  page.waitForEvent('popup'),
  page.locator('#open-portal-btn').click(),
]);
await popup.waitForLoadState();
const title = await popup.title();
if (title === 'Secret Portal') console.log('LEVEL_PASSED');
```

`Promise.all` ensures the listener is registered before the click fires — otherwise the popup event could be missed.

