solution:
const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch();
  const context = await browser.newContext();
  const page = await context.newPage();
  await context.addCookies([{
    name: 'nexus-pass',
    value: 'open',
    domain: 'localhost',
    path: '/',
  }]);
  await page.goto('http://localhost:5000/pages/level-22/');
  const [popup] = await Promise.all([
    context.waitForEvent('page'),
    page.locator('#open-nexus-btn').click(),
  ]);
  await popup.waitForLoadState();
  const msg = await popup.locator('#portal-access-msg').textContent();
  if (msg && msg.includes('Nexus Access Granted')) console.log('LEVEL_PASSED');
  await browser.close();
})();

explanation:
Cookies set on a `BrowserContext` are shared across all pages in that context — including popups.

```
const context = await browser.newContext();
await context.addCookies([{ name: 'nexus-pass', value: 'open', domain: 'localhost', path: '/' }]);
const page = await context.newPage();
// ...
const [popup] = await Promise.all([
  context.waitForEvent('page'),   // 'page' event fires for new tabs
  page.locator('#open-nexus-btn').click(),
]);
```

Use `context.waitForEvent('page')` (not `page.waitForEvent('popup')`) when the new tab is opened in the same context.

