const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();
  await page.clock.install();
  await page.goto('http://localhost:5000/pages/level-32/');
  await page.clock.runFor(31000);
  const visible = await page.locator('#awakened-msg').isVisible();
  if (visible) console.log('LEVEL_PASSED');
  await browser.close();
})();

explanation:
`page.clock.install()` takes over the browser's `setTimeout`, `setInterval`, and `Date` — letting you control time in tests. **Must be called before `page.goto()`.**

```
await page.clock.install();
await page.goto('http://localhost:5000/pages/level-32/');
await page.clock.runFor(31000); // fast-forward 31 seconds
await page.locator('#treasure').waitFor({ state: 'visible' });
