solution:
const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();
  await page.goto('http://localhost:5000/pages/level-41/');
  await page.route('**/spell-catalogue.json', async (route) => {
    const response = await route.fetch();
    const body = await response.json();
    if (Array.isArray(body) && body.length > 0) body[0].power = 9000;
    await route.fulfill({ json: body });
  });
  await page.locator('#fetch-btn').click();
  await page.waitForSelector('#spell-list .spell-card, #spell-list div', { state: 'visible' });
  console.log('LEVEL_PASSED');
  await browser.close();
})();

explanation:
`route.fetch(overrides)` lets you modify the request before it goes to the server — changing URL, headers, or body.

```
await page.route('**/api/search', async (route) => {
  const response = await route.fetch({
    headers: { ...route.request().headers(), 'X-Test-Header': 'arcane' },
  });
  await route.fulfill({ response });
});
```

`route.request().headers()` returns the original request headers. You can spread them and add/override specific values.

