  page.waitForEvent('download'),   // start listening first
  page.click('#download-btn'),     // trigger the download second
]);
const name = download.suggestedFilename();
console.log('Downloaded:', name);
if (name === 'report.txt') console.log('LEVEL_PASSED');
```

The `download` object has:
• `suggestedFilename()` — the file name the server suggested
• `path()` — temp file path (async)
• `saveAs(path)` — save to a specific location
• `cancel()` — cancel an in-progress download

