solution:
describe('The Call Counter', () => {
  it('uses calledOnce, calledTwice, calledThrice, and have.callCount', () => {
    cy.visit('/pages/level-80/');
    cy.window().then((win) => {
      cy.spy(win, 'castSpell').as('castSpy');
      cy.stub(win, 'saveProgress').returns({ success: true }).as('saveStub');
    });
    cy.get('#cast-btn').click();
    cy.get('#cast-btn').click();
    cy.get('#cast-btn').click();
    cy.get('#save-btn').click();
    cy.get('@castSpy').should('have.been.calledThrice');
    cy.get('@castSpy').should('have.callCount', 3);
    cy.get('@saveStub').should('have.been.calledOnce');
  });
});

