});

solution:
describe('The Spell Chronicler', () => {
  it('uses calledWith, calledBefore, and calledAfter on spies', () => {
    cy.visit('/pages/level-80/');
    cy.window().then((win) => {
      cy.spy(win, 'castSpell').as('castSpy');
      cy.spy(win, 'sendNotification').as('notifySpy');
    });
    cy.get('#cast-btn').click();
    cy.get('#notify-btn').click();
    cy.get('@castSpy').should('have.been.calledWith', 'Fireball');
    cy.get('@notifySpy').should('have.been.calledWith', 'Orion', 'Meet at the crossroads!');
    cy.get('@castSpy').then((castSpy) => {
      cy.get('@notifySpy').then((notifySpy) => {
        expect(castSpy).to.have.been.calledBefore(notifySpy);
      });
    });
  });
});

