describe('The Return Value Reckoning', () => {
  it('uses have.returned, always.returned, and thrown on spies', () => {
    cy.visit('/pages/level-80/');
    cy.window().then((win) => {
      cy.spy(win, 'castSpell').as('castSpy');
      cy.spy(win, 'loadProgress').as('loadSpy');
      cy.spy(win, 'riskyOperation').as('riskySpy');
    });
    cy.get('#cast-btn').click();
    cy.get('@castSpy').should('have.returned', 'Fireball cast successfully!');
    cy.get('#load-btn').click();
    cy.get('@loadSpy').should('have.been.calledOnce');
    cy.get('#error-btn').click();
    cy.get('@riskySpy').then((spy) => {
      expect(spy).to.have.thrown('Spell backfired!');
    });
  });
});

