class LRUCache {
  constructor(capacity) {
    this._cap = capacity;
    this._cache = new Map();
  }
  get(key) {
    if (!this._cache.has(key)) return -1;
    const val = this._cache.get(key);
    this._cache.delete(key);
    this._cache.set(key, val);
    return val;
  }
  set(key, value) {
    if (this._cache.has(key)) this._cache.delete(key);
    else if (this._cache.size >= this._cap) {
      this._cache.delete(this._cache.keys().next().value);
    }
    this._cache.set(key, value);
  }
}

test('lru eviction', () => {
  const lru = new LRUCache(2);
  lru.set(1, 'a');
  lru.set(2, 'b');
  lru.get(1); // access 1, making 2 the LRU
  lru.set(3, 'c'); // evicts 2
  // TODO: expect(lru.get(2)).toBe(-1); // evicted
  // TODO: expect(lru.get(1)).toBe('a'); // still present
  // TODO: expect(lru.get(3)).toBe('c'); // still present
});

