function hasCycle(graph, node, visited = new Set()) {
  if (visited.has(node)) return true;
  visited.add(node);
  for (const neighbour of graph[node] || []) {
    if (hasCycle(graph, neighbour, visited)) return true;
  }
  return false;
}

