function makeCircuitBreaker(threshold) {
  let failures = 0;
  let open = false;
  return async function call(fn) {
    if (open) throw new Error('Circuit open');
    try {
      const result = await fn();
      failures = 0;
      return result;
    } catch (e) {
      failures++;
      if (failures >= threshold) open = true;
      throw e;
    }
  };
}

