function compose(...middlewares) {
  return function (context, next) {
    let index = -1;
    function dispatch(i) {
      if (i <= index) throw new Error('next() called multiple times');
      index = i;
      const fn = middlewares[i] || next;
      if (!fn) return;
      fn(context, () => dispatch(i + 1));
    }
    dispatch(0);
  };
}

